    def test_unsupported_version_raises_value_error(self):
        offset = len(_MAGIC)
        bad = (
            self.data[:offset]
            + (2).to_bytes(8, "big")
            + self.data[offset + 8:]
        )
        with self.assertRaises(ValueError):
